MM.mnemo[13] = {"cards":[{"id":"ko-k3-0251","w":"조용하다","cs":"tichý; klidný","en":"to be quiet","p":"a","o":"k","ex":"조용한 방","exc":"tichý pokoj (-ㄴ → přívlastek)","m":"Příslovce ‚potichu, tiše‘ je 조용히 (např. 조용히 하세요 = Buďte prosím potichu). Opak 시끄럽다 (hlučný).","tv":["조용해요"]},{"id":"ko-k3-0252","w":"하얗다","cs":"bílý; sněhobílý","en":"to be white","p":"a","o":"k","ex":"하얀 피아노가 너무 예뻐요.","exc":"Ten bílý klavír je tak krásný. (가 → 1. pád)","m":"Nepravidelné časování ㅎ: v přítomném čase 하얘요, před podstatným jménem ㅎ vypadá → 하얀 (하얀 눈 = bílý sníh). Opak 까맣다 (černý).","tv":["하얘요"],"irr":"ㅎ"},{"id":"ko-k3-0253","w":"달다","cs":"sladký","en":"to be sweet","p":"a","o":"k","ex":"단 거 좋아해요?","exc":"Máš rád sladké? (-ㄴ → přívlastek: 달다 → 단)","m":"ㄹ odpadá před -ㄴ: 단 거 = něco sladkého. Opak 쓰다 (hořký). Stejně znějící 달다 = pověsit.","tv":["달아요"],"irr":"ㄹ (odpadá)"},{"id":"ko-k3-0254","w":"차갑다","cs":"studený; chladný (na dotek, o věcech a nápojích)","en":"to be cold (to the touch)","p":"a","o":"k","ex":"차가운 커피 마시고 싶어요.","exc":"Chci pít studenou kávu. (-고 싶다 → chtít)","m":"Nepravidelné časování ㅂ → 차가워요, před podstatným jménem 차가운. Používá se pro věci, nápoje nebo odměřené chování (na počasí je 춥다). Opak 뜨겁다 (horký).","tv":["차가워요"],"irr":"ㅂ"},{"id":"ko-k3-0255","w":"나쁘다","cs":"špatný; zlý","en":"to be bad","p":"a","o":"k","ex":"나쁜 사람이에요.","exc":"Je to zlý člověk. (-ㄴ → přívlastek; -이에요 → být)","m":"Nepravidelné časování ㅡ → 나빠요. Před podstatným jménem má tvar 나쁜 (나쁜 습관 = zlozvyk). Opak 좋다 (dobrý).","tv":["나빠요"]},{"id":"ko-k3-0256","w":"많다","cs":"četný; mnoho; hodně","en":"to be many, to be a lot","p":"a","o":"k","ex":"여기 사람들이 많아요.","exc":"Je tu hodně lidí. (들 → množné číslo; 이 → 1. pád)","m":"Výslovnost [만타], před samohláskou se ㅎ nevyslovuje: [마나요] (많아요). Před podstatným jménem má tvar 많은 (많은 사람 = mnoho lidí). Opak 적다 (málo).","tv":["많아요"]},{"id":"ko-k3-0257","w":"아이디어","cs":"nápad; myšlenka","en":"idea","p":"n","o":"e","ex":"좋은 아이디어예요.","exc":"To je dobrý nápad. (-은 → přívlastek; -예요 → být)","m":"Výpůjčka z anglického idea (nápad). Často se používá v pracovním či tvůrčím kontextu, v běžné řeči také ryze korejské 생각."},{"id":"ko-k3-0259","w":"피아노","cs":"klavír; piáno","en":"piano","p":"n","o":"e","ex":"하얀 피아노가 너무 예뻐요.","exc":"Ten bílý klavír je tak krásný. (가 → 1. pád)","m":"Výpůjčka z anglického piano. Hrát na klavír se korejsky řekne 피아노를 치다 (doslova ‚udeřit na klavír‘)."},{"id":"ko-k3-0262","w":"생각","cs":"myšlenka; nápad; názor","en":"thought, idea","p":"n","o":"k","ex":"좋은 생각","exc":"dobrý nápad; dobrá myšlenka (-은 → přívlastek)","m":"Častá spojení: 좋은 생각이에요 (To je dobrý nápad), 제 생각에는… (Podle mého názoru…). Sloveso 생각하다 = myslet, přemýšlet."},{"id":"ko-k3-0263","w":"더","cs":"více; víc","en":"more","p":"o","o":"k","ex":"더 작은 가방 있어요?","exc":"Máte menší tašku? (-은 → přívlastek)","m":"Používá se před přídavným jménem nebo slovesem pro stupňování (더 크다 = větší, 더 먹다 = jíst víc). Opak 덜 (méně)."}],"gram":{"id":"ko-k3-g13","w":"-(으)ㄴ + 명사","en":"Making Adjectives (Part 1)","cs":"přívlastkový tvar přídavných jmen (jaký?)","vy":"V korejštině mají přídavná jména v základním tvaru slovesnou podobu (např. 작다 = být malý). Když je chceme postavit přímo před podstatné jméno jako přívlastek (‚malý dům‘), připojíme ke kmeni koncovku -ㄴ (po samohlásce, např. 비싸다 → 비싼) nebo -은 (po souhlásce, např. 작다 → 작은). U kmenů končících na ㄹ toto ㄹ odpadá a nahradí se -ㄴ (달다 → 단), u nepravidelných na ㅂ se ㅂ změní na 우 a přidá se -ㄴ (춥다 → 추운).","m":"Přívlastkový tvar s -(으)ㄴ stojí vždy před podstatným jménem (예쁜 꽃 = hezká květina), nikdy ne na konci věty před sponou 이다 (nikdy ne 예쁜이에요, ale vyčasované 예뻐요). Výjimkou jsou přídavná jména končící na 있다/없다 (např. 맛있다, 재미있다), která berou -는 (맛있는 것).","s":[["작은 집","malý dům (작다 → 작은)"],["빠른 차","rychlé auto (빠르다 → 빠른)"],["조용한 방","tichý pokoj (조용하다 → 조용한)"],["비싼 컴퓨터","drahý počítač (비싸다 → 비싼)"],["하얀 · 그런 · 단","bílý · takový · sladký (výjimky: 하얗다, 그렇다, 달다)"],["예쁜이에요 ( x ) → 예뻐요 ( o )","Nikdy přívlastkový tvar + 이에요: slovo se musí vyčasovat."],["좋은 아이디어예요.","To je dobrý nápad."],["이상한 사람이에요.","Je to divný člověk."],["더 작은 가방 있어요?","Máte menší tašku?"],["차가운 커피 마시고 싶어요.","Chci si dát studenou kávu."],["나쁜 사람이에요.","Je to špatný člověk."],["주연 씨, 큰 우산 있어요?","Džujon, máš velký deštník?"],["더 큰 가방 있어요?","Máte větší tašku?"],["맛있는 것 먹고 싶어요.","Chci si dát něco dobrého."],["하얀 피아노가 너무 예뻐요.","Ten bílý klavír je moc hezký."],["단 거 좋아해요?","Máš rád sladké? / Máš rád sladké věci?"],["그런 이야기 많이 들었어요.","Takových řečí už jsem slyšel spoustu."]]}};
